package br.com.admeclesial.infrastructure.persistence.projeto;
import br.com.admeclesial.domain.projeto.UtilizacaoRecurso; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.util.*;
public interface UtilizacaoRecursoRepository extends JpaRepository<UtilizacaoRecurso,Long>{ Optional<UtilizacaoRecurso> findByUuid(UUID uuid); List<UtilizacaoRecurso> findAllByFonteRecursoProjetoIdOrderByIdAsc(Long fonteId); @Query("select coalesce(sum(u.valor),0) from UtilizacaoRecurso u where u.fonteRecursoProjetoId=:fonteId") BigDecimal sumValorUtilizadoPorFonte(@Param("fonteId") Long fonteId); @Query("select coalesce(sum(u.valor),0) from UtilizacaoRecurso u where u.movimentacaoFinanceiraId=:movId") BigDecimal sumValorUtilizadoPorMovimentacao(@Param("movId") Long movId); @Query("select coalesce(sum(u.valor),0) from UtilizacaoRecurso u where u.fonteRecursoProjetoId in (select f.id from FonteRecursoProjeto f where f.projetoId=:projetoId)") BigDecimal sumValorUtilizadoPorProjeto(@Param("projetoId") Long projetoId); }
